module.exports = async function(data) {
    const { origin, role } = data.$accountability;
    const { clubId, playerId } = data.$trigger.body;

    const id = clubId || playerId;
    if (!role || !origin || !id) throw new Error('Unauthorized');

    const isClub = !!clubId;
    const amount = isClub ? 169 : 49;
    const itemName = isClub ? 'Club Activation' : 'Player Subscription';
    const itemCategory = isClub ? 'Club Activation' : 'Player Subscription';
    const redirectPath = isClub ? `/club/${id}` : `/profile`;

    function encodeBase64(str) {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
        let b64 = '';
        let i = 0;
        while (i < str.length) {
            let c1 = str.charCodeAt(i++) || 0;
            let c2 = str.charCodeAt(i++) || 0;
            let c3 = str.charCodeAt(i++) || 0;

            let e1 = c1 >> 2;
            let e2 = ((c1 & 3) << 4) | (c2 >> 4);
            let e3 = ((c2 & 15) << 2) | (c3 >> 6);
            let e4 = c3 & 63;

            if (isNaN(str.charCodeAt(i - 2))) { e3 = e4 = 64; }
            else if (isNaN(str.charCodeAt(i - 1))) { e4 = 64; }

            b64 += chars.charAt(e1) + chars.charAt(e2) + 
                   (e3 === 64 ? '=' : chars.charAt(e3)) + 
                   (e4 === 64 ? '=' : chars.charAt(e4));
        }
        return b64;
    }

    const apiKey = data.read_payment_settings[0].api_key;
    const stringToEncode = apiKey + ":";
    const base64Token = encodeBase64(stringToEncode);
    const authHeader = `Basic ${base64Token}`;

    const requestBody = {
        external_id: id,
        amount,
        description: `Invoice for ${itemName}`,
        invoice_duration: 86400,
        customer_notification_preference: {
            invoice_created: ["whatsapp", "email", "viber"],
            invoice_reminder: ["whatsapp", "email", "viber"],
            invoice_paid: ["whatsapp", "email", "viber"]
        },
        success_redirect_url: `${origin}/#${redirectPath}`,
        failure_redirect_url: `${origin}/#${redirectPath}`,
        currency: "PHP",
        items: [
            {
                name: itemName,
                quantity: 1,
                price: amount,
                category: itemCategory,
            }
        ],
    };

    return { authHeader, body: requestBody };
}

