  const err = data.del_verify_req || {};
  const st = err.status || (err.response && err.response.status) || 0;
  const msg = String(err.message || (err.data && err.data.message) || '');
  const gone = st === 410 || st === 404 || st === 400 || /deleted|not found|does not exist/i.test(msg);
  return {
    status: gone ? 'deleted' : 'delete_failed',
    matchKey: data.prepare.matchKey,
    error: gone ? null : 'DUPR delete failed: ' + (msg || ('HTTP ' + st)),
    now: new Date().toISOString()
