module.exports = async function(data) {
  const ready = data.build_payloads?.ready || [];
  const failed = data.build_payloads?.failed || [];
  const env = data.build_payloads?.env;
  const userId = data.prepare_matches?.userId;
  const now = new Date().toISOString();

  const resp = data.submit_batch;
  const body = resp?.data ?? resp;
  const res = body?.result ?? {};
  const matchCodes = Array.isArray(res.matchCodes) ? res.matchCodes : [];
  const errors = Array.isArray(res.errors) ? res.errors : [];
  const okMap = {};
  for (const mc of matchCodes) okMap[mc.identifier] = mc;
  const errMap = {};
  for (const e of errors) if (e.identifier) errMap[e.identifier] = e.error || 'DUPR rejected this match';

  const allResults = [];
  for (const f of failed) allResults.push({ matchKey: f.matchKey, status: 'failed', error: f.error });
  for (const m of ready) {
    const id = m.matchKey;
    if (okMap[id]) {
      allResults.push({ matchKey: id, status: 'submitted', duprMatchCode: okMap[id].matchCode, duprHashedMatchCode: okMap[id].hashedMatchCode });
    } else if (errMap[id]) {
      const err = errMap[id];
      // Self-heal: if DUPR says the identifier already exists, the match IS on
      // DUPR under our key — capture the match code and mark submitted so
      // orphaned rows (missing dupr_match_code) relink instead of dead-ending.
      const dup = String(err).match(/already exists[^\d]*(?:ID[:\s]*)?(\d+)/i);
      if (dup) {
        allResults.push({ matchKey: id, status: 'submitted', duprMatchCode: dup[1] });
      } else {
        allResults.push({ matchKey: id, status: 'failed', error: err });
      }
    } else if (body?.status === 'FAILURE' || resp?.status >= 400 || resp instanceof Error) {
      allResults.push({ matchKey: id, status: 'failed', error: body?.message || resp?.message || 'DUPR request failed' });
    } else {
      allResults.push({ matchKey: id, status: 'unknown', error: 'No result returned by DUPR' });
    }
  }
  return { resultsJson: JSON.stringify(allResults), userId, env, now, submitted: allResults.filter(r=>r.status==='submitted').length, failedCount: allResults.filter(r=>r.status==='failed').length, unknown: allResults.filter(r=>r.status==='unknown').length, total: allResults.length };
}

