module.exports = async function(data) {
  const matches = data.read_matches || [];
  const connections = data.read_connections || [];
  const env = data.prepare_matches.environment;

  const connMap = {};
  for (const c of connections) {
    connMap[c.user] = c;
  }

  const results = [];

  for (const m of matches) {
    const teamA = m.team_a || [];
    const teamB = m.team_b || [];
    const allPlayers = [...teamA, ...teamB];

    const duprIds = [];
    const missingDupr = [];

    for (const p of allPlayers) {
      // Fall back to the live dupr_connection — the completed-match snapshot
      // may predate the player's SSO connect.
      const live = p.userId ? connMap[p.userId] : null;
      const effective = p.duprId || (live && live.dupr_id);
      if (effective) {
        p.duprId = effective; // normalize so payload uses it
        duprIds.push(effective);
      } else {
        missingDupr.push(p.username || p.name || 'unknown');
      }
    }

    if (missingDupr.length > 0) {
      results.push({
        matchKey: m.match_key,
        status: 'failed',
        error: 'Players not connected to DUPR: ' + missingDupr.join(', ')
      });
      continue;
    }

    // User gating (DUPR compliance): every player must hold BASIC_L1.
    // Checked via the connection's stored eligibility — requires the
    // player to have (re)connected via SSO since entitlements were added.
    const ineligible = [];
    for (const p of allPlayers) {
      const conn = p.userId ? connMap[p.userId] : null;
      const eligible = conn && conn.eligibility && conn.eligibility.eligible === true;
      if (!eligible) {
        ineligible.push(p.firstName || p.username || p.name || 'unknown');
      }
    }
    if (ineligible.length > 0) {
      results.push({
        matchKey: m.match_key,
        status: 'failed',
        error: 'Players missing DUPR entitlement (BASIC_L1): ' + ineligible.join(', ') + ' — they must reconnect DUPR'
      });
      continue;
    }

    const uniqueIds = [...new Set(duprIds)];
    if (uniqueIds.length !== duprIds.length) {
      results.push({
        matchKey: m.match_key,
        status: 'failed',
        error: 'Duplicate player in match'
      });
      continue;
    }

    if (m.team_a_score === m.team_b_score) {
      results.push({
        matchKey: m.match_key,
        status: 'failed',
        error: 'Tied scores are not allowed'
      });
      continue;
    }

    const dateStr = new Date(m.completed_at).toISOString().split('T')[0];
    const format = m.match_type === 'singles' ? 'SINGLES' : 'DOUBLES';

    const payload = {
      identifier: m.match_key,
      matchDate: dateStr,
      teamA: {
        player1: teamA[0]?.duprId || '',
        player2: teamA[1]?.duprId || '',
        game1: m.team_a_score,
        game2: 0,
        game3: 0,
        game4: 0,
        game5: 0
      },
      teamB: {
        player1: teamB[0]?.duprId || '',
        player2: teamB[1]?.duprId || '',
        game1: m.team_b_score,
        game2: 0,
        game3: 0,
        game4: 0,
        game5: 0
      },
      format: format,
      event: 'Open Play',
      matchType: 'RALLY',
      matchSource: 'PARTNER',
      matchPlayType: 'RECREATIONAL'
    };

    if (format === 'SINGLES') {
      delete payload.teamA.player2;
      delete payload.teamB.player2;
    }

    results.push({
      matchKey: m.match_key,
      matchId: m.match_id,
      club: m.club,
      status: 'ready',
      payload
    });
  }

  const ready = results.filter(r => r.status === 'ready');
  const failed = results.filter(r => r.status === 'failed');

  return {
    results,
    ready,
    failed,
    env,
    payloadJson: JSON.stringify(ready.map(r => r.payload))
  };
}

module.exports = async function(data) {
  const settings = data.read_settings[0];
  const str = settings.client_key + ':' + settings.client_secret;

  // Pure JS Base64 encoder (no Buffer/btoa needed)
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let output = '';
  for (let i = 0; i < str.length; i += 3) {
    const a = str.charCodeAt(i) & 0xff;
    const b = i + 1 < str.length ? str.charCodeAt(i + 1) & 0xff : NaN;
    const c = i + 2 < str.length ? str.charCodeAt(i + 2) & 0xff : NaN;
    const triplet = (a << 16) | ((b || 0) << 8) | (c || 0);
    output += chars[(triplet >> 18) & 63];
    output += chars[(triplet >> 12) & 63];
    output += isNaN(b) ? '=' : chars[(triplet >> 6) & 63];
    output += isNaN(c) ? '=' : chars[triplet & 63];
  }

  return { authHeader: output };
}

