module.exports = async function(data) {
  const creds = data.read_credentials;
  if (!creds || !creds[0]) {
    throw new Error('No credentials found for connection');
  }
  const c = creds[0];
  const settings = data.read_settings[0];
  const apiBase = settings.api_base_url;

  // Check if access token is still valid
  const now = new Date();
  const accessExpires = new Date(c.access_expires_at);
  if (accessExpires > now) {
    return {
      refreshed: false,
      accessToken: c.access_token,
      credentialId: c.id,
      connectionId: c.connection
    };
  }

  // Check if refresh token is still valid
  const refreshExpires = new Date(c.refresh_expires_at);
  if (refreshExpires <= now) {
    throw new Error('Refresh token expired — user must re-authenticate via SSO');
  }

  // Call DUPR refresh endpoint
  const response = await fetch(apiBase + '/auth/v1.0/refresh-token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      refreshToken: c.refresh_token
    })
  });

  if (!response.ok) {
    throw new Error('DUPR refresh failed: ' + response.status);
  }

  const result = await response.json();
  const newAccessToken = result.accessToken || result.access_token || result.result?.accessToken;
  const newRefreshToken = result.refreshToken || result.refresh_token || result.result?.refreshToken;

  if (!newAccessToken || !newRefreshToken) {
    throw new Error('DUPR refresh returned no tokens');
  }

  // UAT: access=7days, refresh=30days. Production: access=30days, refresh=90days
  const env = settings.environment || 'uat';
  const accessDays = env === 'production' ? 30 : 7;
  const refreshDays = env === 'production' ? 90 : 30;

  return {
    refreshed: true,
    accessToken: newAccessToken,
    refreshToken: newRefreshToken,
    accessExpiresAt: new Date(Date.now() + accessDays * 24 * 60 * 60 * 1000).toISOString(),
    refreshExpiresAt: new Date(Date.now() + refreshDays * 24 * 60 * 60 * 1000).toISOString(),
    credentialId: c.id,
    connectionId: c.connection
  };
}

module.exports = async function(data) {
  const body = data.$trigger.body || {};
  const event = body.event;
  const message = body.message || {};

  // Registration handshake / unrelated events: acknowledge, don't error
  if (event !== 'RATING' && event !== 'RATING_SEED') {
    return { skipped: true, reason: 'Ignored event: ' + (event || 'none/handshake') };
  }

  const duprId = message.duprId;
  const rating = message.rating;
  const metrics = message.metrics;
  const timestamp = message.timestamp || new Date().toISOString();

  if (!duprId) {
    return { skipped: true, reason: 'No duprId in webhook message' };
  }

  // rating and metrics can be null for unrated players
  const singlesRating = rating?.singles ?? null;
  const doublesRating = rating?.doubles ?? null;

  return {
    skipped: false,
    event,
    duprId,
    singlesRating,
    doublesRating,
    metrics: metrics ? JSON.stringify(metrics) : null,
    timestamp
  };
}

