module.exports = async function(data) {
  const envelope = data.verify_identity;
  const body = data.$trigger.body;

  const verified = envelope?.data ?? envelope;
  const userInfo = verified?.result || (Array.isArray(verified?.results) ? verified.results[0] : null);
  if (!verified || verified.status !== 'SUCCESS' || !userInfo || !userInfo.duprId) {
    throw new Error('DUPR identity verification failed: ' + JSON.stringify(verified).slice(0, 300));
  }

  const now = new Date().toISOString();
  const env = data.read_settings[0].environment || 'uat';
  const accessDays = env === 'production' ? 30 : 7;
  const refreshDays = env === 'production' ? 90 : 30;
  const accessExpires = new Date(Date.now() + accessDays * 24 * 60 * 60 * 1000).toISOString();
  const refreshExpires = new Date(Date.now() + refreshDays * 24 * 60 * 60 * 1000).toISOString();

  const pick = (v) => {
    if (v == null) return null;
    if (typeof v === 'number') return v;
    if (typeof v === 'object') return v.rating ?? v.value ?? null;
    return null;
  };
  const stats = body.stats || {};
  const singlesRating = pick(userInfo.singlesRating) ?? pick(userInfo.singles) ?? pick(userInfo.ratings?.singles) ?? pick(stats.singlesRating) ?? pick(stats.singles) ?? null;
  const doublesRating = pick(userInfo.doublesRating) ?? pick(userInfo.doubles) ?? pick(userInfo.ratings?.doubles) ?? pick(stats.doublesRating) ?? pick(stats.doubles) ?? null;

  const isUuid = (v) => typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
  const userId = data.$accountability?.user || (isUuid(body.userId) ? body.userId : null);
  if (!userId) throw new Error('Cannot resolve Directus user for DUPR connection');

  // Entitlements from fetch_entitlements request op (POST /subscription/active).
  // Non-fatal: op may have rejected - eligibility stays null.
  let eligibility = null;
  let eligibilityCheckedAt = null;
  try {
    const ej = data.fetch_entitlements?.data ?? data.fetch_entitlements;
    const subs = Array.isArray(ej?.subscriptions) ? ej.subscriptions : [];
    const ent = {};
    for (const s of subs) {
      const e = s?.entitlements || {};
      for (const k of Object.keys(e)) ent[k] = Array.from(new Set([...(ent[k] || []), ...(e[k] || [])]));
    }
    if (subs.length > 0 || Object.keys(ent).length > 0) {
      eligibility = { entitlements: ent, eligible: (ent.tournaments || []).includes('BASIC_L1') };
      eligibilityCheckedAt = now;
    }
  } catch (e) { /* non-fatal */ }

  return {
    duprId: userInfo.duprId,
    userId,
    accessToken: body.accessToken,
    refreshToken: body.refreshToken,
    singlesRating,
    doublesRating,
    eligibility: eligibility ? JSON.stringify(eligibility) : null,
    eligibilityCheckedAt,
    environment: env,
    now,
    accessExpires,
    refreshExpires
  };
}

