module.exports = async function(data) {
  const match = (data.read_match || [])[0];
  const sub = (data.read_submission || [])[0];
  const o = data.prepare.override || {};
  const token = data.get_partner_token;
  const partnerToken = (token && token.result && token.result.token) || (token && token.data && token.data.result && token.data.result.token) || (token && token.token);
  const now = new Date().toISOString();
  const matchKey = data.prepare.matchKey;
  if (!partnerToken) throw new Error('Failed to get partner access token');

  if (!sub || !sub.dupr_match_code) {
    return { proceed: false, status: 'not_submitted', matchKey: matchKey, error: null, now: now };
  }

  // Deleted on DUPR — nothing to update (identifier stays claimed; needs Reactivate)
  if (sub.status === 'deleted') {
    return { proceed: false, status: 'deleted', matchKey: matchKey, error: 'Match was deleted on DUPR — cannot update', now: now };
  }

  const src = match || {};
  const teamA = o.teamA || src.team_a || [];
  const teamB = o.teamB || src.team_b || [];
  const scoreA = o.teamAScore !== undefined ? o.teamAScore : src.team_a_score;
  const scoreB = o.teamBScore !== undefined ? o.teamBScore : src.team_b_score;
  const completedAt = o.completedAt || src.completed_at;
  const matchType = o.matchType || src.match_type || 'doubles';

  const format = matchType === 'singles' ? 'SINGLES' : 'DOUBLES';
  const need = format === 'DOUBLES' ? 2 : 1;
  if (teamA.length < need || teamB.length < need || scoreA === undefined || scoreB === undefined || !completedAt) {
    return { proceed: false, status: 'failed', matchKey: matchKey, error: 'Incomplete match data — pass full match override', now: now };
  }

  const all = [...teamA, ...teamB];
  const missing = all.filter(p => !p.duprId).map(p => p.username || p.name || 'unknown');
  if (missing.length) {
    return { proceed: false, status: 'failed', matchKey: matchKey, error: 'Players not connected to DUPR: ' + missing.join(', '), now: now };
  }
  const ids = all.map(p => p.duprId);
  if (new Set(ids).size !== ids.length) {
    return { proceed: false, status: 'failed', matchKey: matchKey, error: 'Duplicate player in match', now: now };
  }
  if (scoreA === scoreB) {
    return { proceed: false, status: 'failed', matchKey: matchKey, error: 'Tied scores are not allowed', now: now };
  }

  const dateStr = new Date(completedAt).toISOString().split('T')[0];
  const payload = {
    matchId: Number(sub.dupr_match_code),
    identifier: matchKey,
    matchDate: dateStr,
    teamA: { player1: teamA[0].duprId, game1: scoreA },
    teamB: { player1: teamB[0].duprId, game1: scoreB },
    format: format,
    matchType: 'RALLY',
    matchSource: 'PARTNER',
    event: 'Open Play'
  };
  if (format === 'DOUBLES') {
    payload.teamA.player2 = teamA[1].duprId;
    payload.teamB.player2 = teamB[1].duprId;
  }

  return {
    proceed: true,
    matchKey: matchKey,
    now: now,
    url: data.prepare.apiBaseUrl + '/match/v1.0/update',
    authHeader: 'Bearer ' + partnerToken,
    body: JSON.stringify(payload)
  };
}

